import React, { forwardRef, useLayoutEffect, useRef, useState } from 'react';
import { useIntl } from 'react-intl';
import styled from 'styled-components';

import Colors from '@dynatrace/strato-design-tokens/colors';
import Elevations from '@dynatrace/strato-design-tokens/elevations';

import { ProgressCircle } from '../../core/components/progress/ProgressCircle.js';
import { useMergeRefs } from '../../core/hooks/useMergeRefs.js';
import { Flex } from '../../layouts-core/flex/Flex.js';

// #region StyledComponents
interface StyledLoadingWrapperProps {
  $loaderBackground?: string;
  $leftOffset: number;
}

const StyledFlex = /* @__PURE__ */ styled(Flex).attrs<{
  $loaderBackground?: string;
  $leftOffset: number;
}>(({ $loaderBackground, $leftOffset }) => ({
  style: {
    background:
      $loaderBackground === 'transparent'
        ? 'transparent'
        : Colors.Background.Surface.Backdrop,
    left: `${$leftOffset}px`,
  },
}))<StyledLoadingWrapperProps>({
  justifyContent: 'center',
  alignItems: 'center',
  zIndex: Elevations.Default,
  width: '100%',
  height: '100%',
  position: 'absolute',
  top: 0,
});
// #endregion StyledComponents

type LoadingStateProps = {
  loaderBackground?: 'transparent' | undefined;
  leftOffset?: number;
};

export const LoadingState = forwardRef<HTMLElement, LoadingStateProps>(
  ({ loaderBackground, leftOffset }, forwardedRef) => {
    const [height, setHeight] = useState(0);
    const localRef = useRef<HTMLDivElement | null>(null);
    const rootRef = useMergeRefs([localRef, forwardedRef]);

    const intl = useIntl();

    useLayoutEffect(() => {
      if (localRef.current) {
        setHeight(localRef.current.clientHeight);
      }
    }, [localRef.current?.clientHeight]);

    return (
      <StyledFlex
        ref={rootRef}
        $loaderBackground={loaderBackground}
        $leftOffset={leftOffset ?? 0}
      >
        <ProgressCircle
          data-testid="progress-circle"
          size={height < 100 ? 'small' : 'large'}
          aria-label={intl.formatMessage({
            defaultMessage: 'Loading data',
            id: 'EWfCcasdyt/QUnjk',
            description: 'Label for DataTable loading state.',
          })}
        />
      </StyledFlex>
    );
  },
);

(LoadingState as typeof LoadingState & { displayName: string }).displayName =
  'LoadingState';
